import crypto from "node:crypto";
import fs from "node:fs/promises";
import path from "node:path";

import { getPrivateMediaDir, getPublicMediaDir } from "../config.ts";

/**
 * File storage for report media.
 *
 * Keys are generated by the server (`<uuid>.<ext>`); user-supplied filenames
 * never reach the filesystem. `assertSafeKey` is a second line of defence
 * against traversal if a key ever comes from the database.
 */

export type MediaScope = "private" | "public";

const KEY_PATTERN = /^[0-9a-f-]{36}\.(jpg|png|webp)$/;

export function newMediaKey(extension: "jpg" | "png" | "webp"): string {
  return `${crypto.randomUUID()}.${extension}`;
}

export function assertSafeKey(key: string): void {
  if (!KEY_PATTERN.test(key)) {
    throw new Error("Unsafe media key");
  }
}

function directory(scope: MediaScope): string {
  return scope === "private" ? getPrivateMediaDir() : getPublicMediaDir();
}

export async function writeMedia(
  scope: MediaScope,
  key: string,
  data: Uint8Array,
): Promise<void> {
  assertSafeKey(key);
  const dir = directory(scope);
  await fs.mkdir(dir, { recursive: true });
  await fs.writeFile(path.join(dir, key), data, { mode: 0o600 });
}

export async function readMedia(scope: MediaScope, key: string): Promise<Buffer> {
  assertSafeKey(key);
  return fs.readFile(path.join(directory(scope), key));
}

export async function removeMedia(scope: MediaScope, key: string): Promise<void> {
  assertSafeKey(key);
  await fs.rm(path.join(directory(scope), key), { force: true });
}
